//! Rust translation of `trace/events/netlink.h`.
//!
//! The source is a Linux tracepoint header.  `TRACE_EVENT`, `__string`,
//! `__assign_str`, and `__get_str` are supplied by the kernel tracing
//! infrastructure and therefore remain represented here as the corresponding
//! declaration and operation comments rather than being reimplemented.

use core::ffi::c_char;

/// Payload declared by `TP_STRUCT__entry(__string(msg, msg))`.
///
/// The actual storage and accessor are generated by the Linux tracepoint
/// macros; this raw pointer preserves the source field's C string interface.
#[repr(C)]
pub struct netlink_extack_entry {
    pub msg: *const c_char,
}

/// `TRACE_EVENT(netlink_extack, ...)`
///
/// C declaration:
/// `TP_PROTO(const char *msg)`
///
/// The tracepoint emission operation is provided externally by the tracepoint
/// framework.  Its assignment is `__assign_str(msg)`, and its print format is
/// `msg=%s` using `__get_str(msg)`.
extern "C" {
    pub fn trace_netlink_extack(msg: *const c_char);
}


